from typing import List

class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m, n = len(coins), len(coins[0])
        NEG_INF = -10 ** 15

        # dp[i][j][k] = max coins at (i, j) having used k neutralizations
        dp = [[[NEG_INF] * 3 for _ in range(n)] for _ in range(m)]

        # Base case: starting cell (0, 0)
        val = coins[0][0]
        if val >= 0:
            dp[0][0][0] = val
        else:
            dp[0][0][0] = val          # no neutralize
            dp[0][0][1] = 0            # neutralize at start

        # Helper to update dp for a neighbour
        def update(i, j, ni, nj):
            val = coins[i][j]
            for k_prev in range(3):
                prev = dp[ni][nj][k_prev]
                if prev == NEG_INF:
                    continue
                if val >= 0:
                    # No neutralization needed
                    new_k = k_prev
                    new_sum = prev + val
                    if new_sum > dp[i][j][new_k]:
                        dp[i][j][new_k] = new_sum
                else:
                    # Option 1: let the robber steal
                    new_k = k_prev
                    new_sum = prev + val
                    if new_sum > dp[i][j][new_k]:
                        dp[i][j][new_k] = new_sum
                    # Option 2: neutralize if we have spare
                    if k_prev < 2:
                        new_k2 = k_prev + 1
                        new_sum2 = prev   # no coins lost
                        if new_sum2 > dp[i][j][new_k2]:
                            dp[i][j][new_k2] = new_sum2

        for i in range(m):
            for j in range(n):
                if i == 0 and j == 0:
                    continue
                if i > 0:
                    update(i, j, i - 1, j)
                if j > 0:
                    update(i, j, i, j - 1)

        return max(dp[m - 1][n - 1])

