def is_simple_power(x, n):
    """Return True if x is an integer power of n (i.e. n**k == x for some integer k)."""
    # Handle special cases
    if n == 1:
        return x == 1
    if x <= 0 or n == 0 or n == -1:
        return False

    power = 1
    while power < x:
        power *= n
    return power == x
