class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        # Generate all substrings including the empty string
        def substrings(string: str):
            subs = [""]  # include empty substring
            n = len(string)
            for i in range(n):
                for j in range(i + 1, n + 1):
                    subs.append(string[i:j])
            return subs

        subs_s = substrings(s)
        subs_t = substrings(t)

        max_len = 0
        for ss in subs_s:
            for tt in subs_t:
                candidate = ss + tt
                if len(candidate) <= max_len:
                    continue
                if candidate == candidate[::-1]:
                    max_len = len(candidate)

        return max_len
