def check_dict_case(dict):
    """
    Given a dictionary, return True if all keys are strings in lower 
    case or all keys are strings in upper case, else return False.
    The function should return False is the given dictionary is empty.
    """
    if not dict:
        return False

    expected_case = None  # 'lower' or 'upper'
    for key in dict:
        if not isinstance(key, str):
            return False

        if key.islower():
            current = 'lower'
        elif key.isupper():
            current = 'upper'
        else:
            # contains mixed or non-alphabetic characters
            return False

        if expected_case is None:
            expected_case = current
        elif expected_case != current:
            return False

    return True
