        def dfs(i: int, pending: int) -> int:
            """
            Minimal cost to remove all elements from index i onwards, with an optional
            pending element at index `pending` (or -1 if none).
            """
            # Number of remaining elements
            remaining = (n - i) + (1 if pending != -1 else 0)
            if remaining <= 2:
                # Remove all remaining elements in a single operation
                if pending == -1:
                    # Only elements from i onwards
                    if remaining == 0:
                        return 0
                    elif remaining == 1:
                        return nums[i]
                    else:  # remaining == 2
                        return max(nums[i], nums[i + 1])
                else:
                    if remaining == 1:
                        return nums[pending]
                    else:  # remaining == 2
                        return max(nums[pending], nums[i])

            # More than two elements remain
            best = float('inf')
            if pending == -1:
                # Candidates: i, i+1, i+2  (all exist because remaining > 2)
                cand = [i, i + 1, i + 2]
                for a, b in itertools.combinations(cand, 2):
                    cost = max(nums[a], nums[b])
                    # Remaining element
                    r = next(x for x in cand if x != a and x != b)
                    # After removing two from the front, the new front is `r`,
                    # and the next index to consider is i+3.
                    best = min(best, cost + dfs(i + 3, r))
            else:
                # Candidates: pending, i, i+1  (i+1 exists because remaining > 2)
                cand = [pending, i, i + 1]
                for a, b in itertools.combinations(cand, 2):
                    cost = max(nums[a], nums[b])
                    r = next(x for x in cand if x != a and x != b)
                    # New front is `r`; next index after the first three is i+2.
                    best = min(best, cost + dfs(i + 2, r))

            return best

        return dfs(0, -1)
